import React,
{
useState
}
from "react";

import Navbar
from "../../components/Navbar";

import Sidebar
from "../../components/Sidebar";

import {
applyLoan
}
from "../../api/loanApi";

import {
getAccountId
}
from "../../utils/auth";

function LoanApplication(){

const [amount,setAmount]
=
useState("");

const [tenureMonths,
setTenureMonths]
=
useState("");

const [message,
setMessage]
=
useState("");

const submitLoan =
async()=>{

try{

await applyLoan({

amount:
parseFloat(amount),

tenureMonths:
parseInt(tenureMonths),

accountId:
getAccountId()

});

setMessage(
"Loan Application Submitted Successfully"
);

setAmount("");
setTenureMonths("");

}
catch(error){

setMessage(
"Loan Application Failed"
);

}

};

return(

<div>

<Navbar/>

<div className="d-flex">

<Sidebar/>

<div className="container p-4">

<div className="card">

<div className="card-header">

Apply Loan

</div>

<div className="card-body">

{
message &&
<div
className=
"alert alert-info"
>
{message}
</div>
}

<div className="form-group">

<label>

Loan Amount

</label>

<input
type="number"
className="form-control"
value={amount}
onChange={(e)=>
setAmount(
e.target.value
)
}
/>

</div>

<div className="form-group">

<label>

Tenure (Months)

</label>

<input
type="number"
className="form-control"
value={tenureMonths}
onChange={(e)=>
setTenureMonths(
e.target.value
)
}
/>

</div>

<button
className=
"btn btn-primary"
onClick={
submitLoan
}
>

Apply Loan

</button>

</div>

</div>

</div>

</div>

</div>

);

}

export default LoanApplication;
